<?php require_once __DIR__.'/../includes/admin-layout.php';admin_start('Depolama noktaları');$rows=db()->query('SELECT r.*,(SELECT COUNT(DISTINCT ir.image_id) FROM image_relays ir WHERE ir.relay_id=r.id AND ir.status="stored") stored_images,(SELECT COUNT(DISTINCT ir.image_id) FROM image_relays ir WHERE ir.relay_id=r.id AND ir.status="failed") failed_images,(SELECT MAX(ir.stored_at) FROM image_relays ir WHERE ir.relay_id=r.id) last_store FROM relays r ORDER BY FIELD(r.status,"offline","slow","healthy"),r.url')->fetchAll();admin_title('DAĞITIK DEPOLAMA','Depolama noktaları','Bağımsız noktaların sağlık, gecikme ve saklanan görsel durumlarını izleyin.');?><section class="relay-admin-grid"><?php foreach($rows as $r):?><article class="admin-card relay-admin-card"><div><i class="status-dot <?=$r['status']==='healthy'?'':($r['status']==='slow'?'warning':'offline')?>"></i><span class="table-status status-<?=e($r['status'])?>"><?=e($r['status'])?></span></div><h2><?=e($r['url'])?></h2><dl><div><dt>Saklanan görsel</dt><dd><?=number_format((int)$r['stored_images'])?></dd></div><div><dt>Başarısız kayıt</dt><dd><?=number_format((int)$r['failed_images'])?></dd></div><div><dt>Gecikme</dt><dd><?=number_format((int)$r['latency'])?> ms</dd></div><div><dt>Son kontrol</dt><dd><?=e($r['last_checked']??'—')?></dd></div><div><dt>Son kayıt</dt><dd><?=e($r['last_store']??'—')?></dd></div><div><dt>Yetkiler</dt><dd><?=!empty($r['read_allowed'])?'R':''?><?=!empty($r['write_allowed'])?' / W':''?></dd></div></dl></article><?php endforeach?></section><?php admin_end();
